def rects(g,color):
    h,w=len(g),len(g[0]); best=[]
    # find maximal all-color rectangles via brute force over bounding boxes
    import itertools
    cells=[(r,c) for r in range(h) for c in range(w) if g[r][c]==color]
    if not cells: return []
    res=set()
    for r1 in range(h):
        for r2 in range(r1,h):
            for c1 in range(w):
                c2=c1
                while c2<w and all(g[r][c2]==color for r in range(r1,r2+1)):
                    res.add(((r2-r1+1),(c2-c1+1)))
                    c2+=1
    return res
